<?php

/**
 * The weight of each byte in the single-byte latin1 collations that are not binary, as WEIGHT_STRING() answers it.
 *
 * Each value holds 256 weights, one byte for each byte of latin1 in order, written in hexadecimal.
 * Read from WEIGHT_STRING(_latin1 X'00' .. X'FF' COLLATE ...) on live 5.7.44 and 8.4.7 servers, which agree.
 * Source: https://dev.mysql.com/doc/refman/8.4/en/charset-we-sets.html.
 */

declare(strict_types=1);

return [
    'latin1_swedish_ci' => '',
    'latin1_general_ci' => '',
    'latin1_general_cs' => '',
    'latin1_danish_ci' => '',
    'latin1_spanish_ci' => '',
    'latin1_german1_ci' => '',
];
